              />
              {errors.ville && <p className="mt-1 text-sm text-red-600">{errors.ville.message}</p>}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Code postal *
              </label>
              <input
                {...register('codePostal')}
