    dossier: 'DOS-2024-002',
    montantHT: 2200,
    montantTTC: 2640,
    statut: 'envoyee',
    dateEmission: '2024-01-10',
    dateEcheance: '2024-02-10',
  },
  {
    id: '3',
    numéro: 'FACT-2024-003',
    client: 'EURL Dupont',
    montantHT: 850,
    montantTTC: 1020,
    statut: 'brouillon',
    dateEmission: '2024-01-15',
    dateEcheance: '2024-02-15',
  },
  {
    id: '4',
    numéro: 'FACT-2024-004',
    client: 'SCI Investissement',
    dossier: 'DOS-2024-004',
    montantHT: 3500,
    montantTTC: 4200,
    statut: 'en_retard',
    dateEmission: '2023-12-20',
