    const montantTTC = montantHT * (1 + tva / 100);

    if (editingFacture) {
      setFactures(prev =>
        prev.map(f =>
          f.id === editingFacture.id
            ? {
                ...f,
                ...data,
                montantHT,
                montantTTC,
